def _calendar_comp_class_by_data(self, data):
    for line in data.split('\n'):
        if line == 'BEGIN:VEVENT':
            return Event
        if line == 'BEGIN:VTODO':
            return Todo
        if line == 'BEGIN:VJOURNAL':
            return Journal
        if line == 'BEGIN:VFREEBUSY':
            return FreeBusy
